                [ 'p', 'Die Antworten haben Sie am besten schriftlich. Stellen Sie Fragen im Feld „Weitere Informationen (optional)“ oder schreiben Sie an Michal@laseryxtool.pl.' ],
                [ 'h2', 'Wer macht was? Der Kauf im Überblick' ],
                [ 'table', [ 'Schritt', 'Wer', 'Was Sie erhalten' ], [
                    [ 'Modellwahl und Demo', 'Sie; in der Demo zeigen wir die Maschine live', 'Ein Modell, das zu Material und Stückzahl passt' ],
                    [ 'Variante, Anzahl, Warenkorb', 'Sie', 'Einen unverbindlichen Preis in Euro' ],
                    [ 'Bestellformular', 'Sie', 'Eine Bestätigung per E-Mail, sofern zugestellt' ],
                    [ 'Prüfung von Verfügbarkeit, Preis, MwSt. und Lieferung', 'Michał', 'Den Endbetrag' ],
